,p_process_name=>'Fetch User Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT',
'        username,',
'        ADM_USER_ID,',
'        org_ID,',
'		upper(JOB_DESC),',
'        FIRSTNAME||'' ''||LASTNAME',
'    INTO        ',
'        :app_user,',
'        :APP_USER_id,',
'        :app_org_id,',
'		:app_USER_ROLE,',
'        :app_user_full_name',
'    FROM',
'        ADM_USER',
'    WHERE',
'        upper(username) = upper(:app_user);',
'',
'   /* select ORG_NAME into :APP_ORG_NAME',
'    from ADM_ORG',
'    where org_id = :app_org_id; */',
'END;'))
