prompt --application/shared_components/security/authentications/facebook
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(352836614870469748519)
,p_name=>'FACEBOOK'
,p_scheme_type=>'NATIVE_SOCIAL'
,p_attribute_01=>wwv_flow_imp.id(131245451698237781236)
,p_attribute_02=>'FACEBOOK'
,p_attribute_07=>'public_profile,email'
,p_attribute_09=>'email'
,p_attribute_10=>'last_name,first_name,picture'
,p_attribute_11=>'Y'
,p_attribute_13=>'Y'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure post_authenticate is',
'  ln_user_id number;',
'begin',
'',
'  begin',
'    select user_id',
'      into ln_user_id',
'      from am_users',
'     where user_name = upper(apex_json.get_varchar2(''email''));',
'  ',
'    update am_users',
'       set ',
'           first_name   = apex_json.get_varchar2(''first_name''),',
'           last_name    = apex_json.get_varchar2(''last_name''),',
'           image_url    = apex_json.get_varchar2(''picture.data.url''),',
'           authenticated_by = ''FACEBOOK''',
'     where user_id = ln_user_id;',
'  ',
'    commit;',
'  exception',
'    when no_data_found then',
'      insert into am_users',
'        (user_id,',
'         user_name,',
'         organization,',
'         password,',
'         first_name,',
'         last_name,',
'         email,',
'         phone,',
'         image_url,',
'         authenticated_by,',
'         enabled,',
'         date_from,',
'         date_to,',
'         created_by,',
'         created_on,',
'         updated_by,',
'         updated_on)',
'      values',
'        (to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.nextval, 7, 0),',
'         upper(apex_json.get_varchar2(''email'')),',
'         null,',
'         null,',
'         apex_json.get_varchar2(''first_name''),',
'         apex_json.get_varchar2(''last_name''),',
'         lower(apex_json.get_varchar2(''email'')),',
'         null,',
'         apex_json.get_varchar2(''picture.data.url''),',
'         ''FACEBOOK'',',
'         ''Y'',',
'         null,',
'         null,',
'         to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.currval, 7, 0),',
'         sysdate,',
'         to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.currval, 7, 0),',
'         sysdate);',
'    ',
'      commit;',
'  end;',
'',
'end;',
''))
,p_invalid_session_type=>'LOGIN'
,p_post_auth_process=>'POST_AUTHENTICATE'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_switch_in_session_yn=>'Y'
,p_version_scn=>1
);
end;
/
prompt --application/shared_components/security/authentications/google
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(353126614784325086560)
,p_name=>'GOOGLE'
,p_scheme_type=>'NATIVE_SOCIAL'
,p_attribute_01=>wwv_flow_imp.id(131246151767103297365)
,p_attribute_02=>'GOOGLE'
,p_attribute_07=>'profile,email'
,p_attribute_09=>'email'
,p_attribute_10=>'profile'
,p_attribute_11=>'Y'
,p_attribute_13=>'Y'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure post_authenticate is',
'  ln_user_id number;',
'begin',
'',
'  begin',
'    select user_id',
'      into ln_user_id',
'      from am_users',
'     where user_name = upper(apex_json.get_varchar2(''email''));',
'  ',
'    update am_users',
'       set organization = upper(apex_json.get_varchar2(''hd'')),',
'           first_name   = apex_json.get_varchar2(''given_name''),',
'           last_name    = apex_json.get_varchar2(''family_name''),',
'           image_url    = apex_json.get_varchar2(''picture''),',
'           authenticated_by = ''GOOGLE''',
'     where user_id = ln_user_id;',
'  ',
'    commit;',
'  exception',
'    when no_data_found then',
'      insert into am_users',
'        (user_id,',
'         user_name,',
'         organization,',
'         password,',
'         first_name,',
'         last_name,',
'         email,',
'         phone,',
'         image_url,',
'         authenticated_by,',
'         enabled,',
'         date_from,',
'         date_to,',
'         created_by,',
'         created_on,',
'         updated_by,',
'         updated_on)',
'      values',
'        (to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.nextval, 7, 0),',
'         upper(apex_json.get_varchar2(''email'')),',
'         upper(apex_json.get_varchar2(''hd'')),',
'         null,',
'         apex_json.get_varchar2(''given_name''),',
'         apex_json.get_varchar2(''family_name''),',
'         lower(apex_json.get_varchar2(''email'')),',
'         null,',
'         apex_json.get_varchar2(''picture''),',
'         ''GOOGLE'',',
'         ''Y'',',
'         null,',
'         null,',
'         to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.currval, 7, 0),',
'         sysdate,',
'         to_char(sysdate, ''YYYYMMDD'') || lpad(am_users_s.currval, 7, 0),',
'         sysdate);',
'    ',
'      commit;',
'  end;',
'',
'end;',
''))
,p_invalid_session_type=>'LOGIN'
,p_post_auth_process=>'POST_AUTHENTICATE'
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
,p_switch_in_session_yn=>'Y'
,p_version_scn=>1
);
end;
