prompt --application/shared_components/plugins/region_type/nl_rokit_cookiebar
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(353086717503563118928)
,p_plugin_type=>'REGION TYPE'
,p_name=>'NL.ROKIT.COOKIEBAR'
,p_display_name=>'rokit CookieBar'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','NL.ROKIT.COOKIEBAR'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION render_cookiebar(p_region                IN apex_plugin.t_region',
'                        , p_plugin                IN apex_plugin.t_plugin',
'                        , p_is_printer_friendly   IN BOOLEAN)',
'   RETURN apex_plugin.t_region_render_result',
'IS',
'   l_render_result      apex_plugin.t_region_render_result;',
'   l_options            VARCHAR2(32767);',
'   --',
'   l_message            VARCHAR2(32767) := p_plugin.attribute_01;',
'   l_acceptbutton       VARCHAR2(32767) := p_plugin.attribute_02;',
'   l_accepttext         VARCHAR2(32767) := p_plugin.attribute_03;',
'   l_acceptfunction     VARCHAR2(32767) := p_plugin.attribute_06;',
'   l_declinebutton      VARCHAR2(32767) := p_plugin.attribute_04;',
'   l_declinetext        VARCHAR2(32767) := p_plugin.attribute_05;',
'   l_declinefunction    VARCHAR2(32767) := p_plugin.attribute_07;',
'   l_policybutton       VARCHAR2(32767) := p_plugin.attribute_08;',
'   l_policytext         VARCHAR2(32767) := p_plugin.attribute_09;',
'   l_policyurl          VARCHAR2(32767) := p_plugin.attribute_10;',
'   l_autoenable         VARCHAR2(32767) := NULL;',
'   l_acceptoncontinue   VARCHAR2(32767) := NULL;',
'   l_acceptonscroll     VARCHAR2(32767) := NULL;',
'   l_acceptanyclick     VARCHAR2(32767) := NULL;',
'   l_expiredays         VARCHAR2(32767) := p_plugin.attribute_11;',
'   l_renewonvisit       VARCHAR2(32767) := NULL;',
'   l_forceshow          VARCHAR2(32767) := p_region.attribute_01;',
'   l_effect             VARCHAR2(32767) := p_region.attribute_02;',
'   l_element            VARCHAR2(32767) := p_region.attribute_03;',
'   l_append             VARCHAR2(32767) := p_region.attribute_04;',
'   l_fixed              VARCHAR2(32767) := p_region.attribute_05;',
'   l_bottom             VARCHAR2(32767) := p_region.attribute_06;',
'   l_zindex             VARCHAR2(32767) := p_region.attribute_07;',
'   l_domain             VARCHAR2(32767) := NULL;',
'   l_referrer           VARCHAR2(32767) := NULL;',
'BEGIN',
'   -- application attributes:',
'   -- -------------------------------------',
'   --message: ''We use cookies to track usage and preferences''',
'   l_options   := ''message: "'' || l_message || ''"'';',
'',
'   --acceptButton: true',
'   --acceptText: ''I Understand''',
'   --acceptFunction: null',
'   IF l_acceptbutton = ''Y''',
'   THEN',
'      l_options   := l_options || '', acceptButton: true'';',
'      l_options   := l_options || '', acceptText: "'' || l_accepttext || ''"'';',
'',
'      IF l_acceptfunction IS NOT NULL',
'      THEN',
'         l_options   := l_options || '', acceptFunction: '' || l_acceptfunction;',
'      END IF;',
'   ELSE',
'      l_options   := l_options || '', acceptButton: false'';',
'   END IF;',
'',
'   --declineButton: false',
'   --declineText: ''Disable Cookies''',
'   --declineFunction: null',
'   IF l_declinebutton = ''Y''',
'   THEN',
'      l_options   := l_options || '', declineButton: true'';',
'      l_options   := l_options || '', declineText: "'' || l_declinetext || ''"'';',
'',
'      IF l_declinefunction IS NOT NULL',
'      THEN',
'         l_options   := l_options || '', declineFunction: '' || l_declinefunction;',
'      END IF;',
'   ELSE',
'      l_options   := l_options || '', declineButton: false'';',
'   END IF;',
'',
'   --policyButton: true',
'   --policyText: ''Privacy Policy''',
'   --policyURL: ''/privacy-policy/''',
'   IF l_policybutton = ''Y''',
'   THEN',
'      l_options   := l_options || '', policyButton: true'';',
'      l_options   := l_options || '', policyText: "'' || l_policytext || ''"'';',
'',
'      l_options   := l_options || '', policyURL: "'' || l_policyurl || ''"'';',
'   ELSE',
'      l_options   := l_options || '', policyButton: false'';',
'   END IF;',
'',
'   --autoEnable: true (what does it do?)',
'   IF l_autoenable = ''Y''',
'   THEN',
'      l_options   := l_options || '', autoEnable: true'';',
'   ELSE',
'      l_options   := l_options || '', autoEnable: false'';',
'   END IF;',
'',
'   --expireDays: 365',
'   l_options   := l_options || '', expireDays: '' || l_expiredays;',
'',
'   --renewOnVisit: false',
'',
'   --domain: ''www.example.com'',',
'   --referrer: ''www.example.com''',
'',
'   -- component attributes:',
'   -- -------------------------------------',
'   --forceShow: false',
'   IF l_forceshow = ''Y''',
'   THEN',
'      l_options   := l_options || '', forceShow: true'';',
'   END IF;',
'',
'   --effect: ''slide''',
'   l_options   := l_options || '', effect: "'' || NVL(l_effect, ''slide'') || ''"'';',
'   --element: ''body''',
'   l_options   := l_options || '', element: "'' || NVL(l_element, ''body'') || ''"'';',
'',
'   --append: false',
'   IF l_append = ''Y''',
'   THEN',
'      l_options   := l_options || '', append: true'';',
'   END IF;',
'',
'   --fixed: false',
'   IF l_fixed = ''Y''',
'   THEN',
'      l_options   := l_options || '', fixed: true'';',
'',
'      --bottom: false',
'      IF l_forceshow = ''Y''',
'      THEN',
'         l_options   := l_options || '', bottom: true'';',
'      END IF;',
'   END IF;',
'',
'   --zindex: ''''',
'',
'   apex_css.add_file(p_name => ''jquery.cookiebar'', p_directory => p_plugin.file_prefix);',
'   apex_javascript.add_library(p_name                    => ''jquery.cookiebar''',
'                             , p_directory               => p_plugin.file_prefix',
'                             , p_check_to_add_minified   => FALSE);',
'   apex_javascript.add_library(p_name                    => ''rokit.cookiebar''',
'                             , p_directory               => p_plugin.file_prefix',
'                             , p_check_to_add_minified   => FALSE);',
'   apex_javascript.add_onload_code(p_code => ''apex.jQuery.cookieBar({'' || l_options || ''});'', p_key => ''rokit_cookiebar'');',
'   RETURN l_render_result;',
'END;'))
,p_api_version=>1
,p_render_function=>'render_cookiebar'
,p_substitute_attributes=>true
,p_version_scn=>1
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
,p_files_version=>4
);
