prompt --application/shared_components/plugins/region_type/com_nikitsky_heatmap_calendar
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(354598643583106077354)
,p_plugin_type=>'REGION TYPE'
,p_name=>'COM.NIKITSKY.HEATMAP_CALENDAR'
,p_display_name=>'Heatmap calendar'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('REGION TYPE','COM.NIKITSKY.HEATMAP_CALENDAR'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function render (',
'    p_region              in apex_plugin.t_region,',
'    p_plugin              in apex_plugin.t_plugin,',
'    p_is_printer_friendly in boolean )',
'    return apex_plugin.t_region_render_result',
'is',
'    l_SellSize      apex_application_page_regions.attribute_01%type := p_region.attribute_01;',
'    l_FirstYear     apex_application_page_regions.attribute_05%type := p_region.attribute_05;',
'    l_Periods       apex_application_page_regions.attribute_06%type := p_region.attribute_06;',
'    l_dateFormat    apex_application_page_regions.attribute_07%type := p_region.attribute_07;',
'    l_legendType    apex_application_page_regions.attribute_08%type := p_region.attribute_08;',
'',
'    l_StartValue    apex_application_page_regions.attribute_09%type := p_region.attribute_09;',
'    l_StartColour   apex_application_page_regions.attribute_10%type := p_region.attribute_10;',
'    l_endValue      apex_application_page_regions.attribute_11%type := p_region.attribute_11;',
'    l_EndColour     apex_application_page_regions.attribute_12%type := p_region.attribute_12;',
'',
'    l_tooltipEnabled boolean;',
'    l_jscode        VARCHAR2(32000);',
'begin',
'',
'    l_tooltipEnabled := p_region.attribute_14 = ''Y'';',
'',
'    APEX_CSS.ADD_FILE (p_name           => ''heatmap_calendar'',',
'                       p_directory      => p_plugin.file_prefix,',
'                       p_skip_extension => false);',
'',
'    --add d3js library',
'    apex_javascript.add_library( p_name                  => ''d3'',',
'                                 p_directory             => p_plugin.file_prefix,',
'                                 p_check_to_add_minified => TRUE );',
'',
'    apex_javascript.add_library( p_name                  => ''heatmap_calendar'',',
'                                 p_directory             => p_plugin.file_prefix,',
'                                 p_check_to_add_minified => TRUE);',
'',
'    -- Output the container for the calendar which is used by the Javascript code',
'    sys.htp.p(''<div id=''||apex_javascript.add_value(sys.htf.escape_sc(p_region.static_id||''_hc''), false)||''></div>'');',
'',
'    -- define variables for calendar',
'    l_jscode :=''heatmap_calendar(''||',
'            apex_javascript.add_value(p_region.static_id)||',
'            ''{''||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''ajaxIdentifier'',',
'                    p_value     => apex_plugin.get_ajax_identifier,',
'                    p_omit_null => false,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''cellSize'',',
'                    p_value     => sys.htf.escape_sc(l_SellSize),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''firstYear'',',
'                    p_value     => sys.htf.escape_sc(l_FirstYear),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''periods'',',
'                    p_value     => sys.htf.escape_sc(coalesce(l_Periods,1)),',
'                    p_omit_null => false,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''dateFormat'',',
'                    p_value     => sys.htf.escape_sc(l_dateFormat),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''legendType'',',
'                    p_value     => sys.htf.escape_sc(l_legendType),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''startValue'',',
'                    p_value     => sys.htf.escape_sc(l_StartValue),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''startColor'',',
'                    p_value     => sys.htf.escape_sc(l_StartColour),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''endValue'',',
'                    p_value     => sys.htf.escape_sc(l_endValue),',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''tooltipEnabled'',',
'                    p_value     => l_tooltipEnabled,',
'                    p_omit_null => true,',
'                    p_add_comma => true',
'                )||',
'                apex_javascript.add_attribute(',
'                    p_name      => ''endColor'',',
'                    p_value     => sys.htf.escape_sc(l_EndColour),',
'                    p_omit_null => true,',
'                    p_add_comma => false',
'                )||',
'            ''}'';',
'    if p_region.init_javascript_code is not null then',
'        l_jscode :=l_jscode||'',''||p_region.init_javascript_code||'');'';',
'    else',
'        l_jscode :=l_jscode||'');'';',
'    end if;',
'    apex_javascript.add_onload_code (',
'        p_code => l_jscode',
'    );',
'',
'    return null;',
'',
'end render;',
'',
'function ajax (',
'    p_region in apex_plugin.t_region,',
'    p_plugin in apex_plugin.t_plugin',
') return apex_plugin.t_region_ajax_result',
'is',
'    -- It''s better to have named variables instead of using the generic ones,',
'    -- makes the code more readable. We are using the same defaults for the',
'    -- required attributes as in the plug-in attribute configuration, because',
'    -- they can still be null. Keep them in sync!',
'    c_day_column          constant varchar2(255) := p_region.attribute_02;',
'    c_value_column        constant varchar2(255) := p_region.attribute_03;',
'    c_label_column        constant varchar2(255) := p_region.attribute_13;',
'',
'    l_day_column_no          pls_integer;',
'    l_value_column_no        pls_integer;',
'    l_label_column_no        pls_integer;',
'',
'    l_column_value_list      apex_plugin_util.t_column_value_list2;',
'',
'    l_value             varchar2(4000);',
'    l_class             varchar2(255);',
'',
'begin',
'    apex_json.initialize_output (',
'        p_http_cache => false );',
'',
'        -- Read the data based on the region source query',
'    l_column_value_list := apex_plugin_util.get_data2 (',
'                               p_sql_statement  => p_region.source,',
'                               p_min_columns    => 2,',
'                               p_max_columns    => null,',
'                               p_component_name => p_region.name );',
'',
'    -- Get the actual column# for faster access and also verify that the data type',
'    -- of the column matches with what we are looking for',
'    l_day_column_no := apex_plugin_util.get_column_no (',
'                            p_attribute_label   => ''Date column'',',
'                            p_column_alias      => c_day_column,',
'                            p_column_value_list => l_column_value_list,',
'                            p_is_required       => true,',
'                            p_data_type         => apex_plugin_util.c_data_type_date',
'    );',
'',
'    l_value_column_no   := apex_plugin_util.get_column_no (',
'                            p_attribute_label   => ''Value column'',',
'                            p_column_alias      => c_value_column,',
'                            p_column_value_list => l_column_value_list,',
'                            p_is_required       => true,',
'                            p_data_type         => apex_plugin_util.c_data_type_number',
'    );',
'',
'    -- label is optional column.',
'    if p_region.attribute_13 is not null then',
'        l_label_column_no   := apex_plugin_util.get_column_no (',
'                                p_attribute_label   => ''Label column'',',
'                                p_column_alias      => c_label_column,',
'                                p_column_value_list => l_column_value_list,',
'                                p_is_required       => true,',
'                                p_data_type         => apex_plugin_util.c_data_type_varchar2',
'        );',
'    end if;',
'',
'        -- begin output as json',
'    owa_util.mime_header(''application/json'', false);',
'    htp.p(''cache-control: no-cache'');',
'    htp.p(''pragma: no-cache'');',
'    owa_util.http_header_close;',
' --   l_message_when_no_data_found := apex_escape.html_whitelist(',
'  --      apex_plugin_util.replace_substitutions (',
'   --             p_value  => c_message_when_no_data_found,',
'   --             p_escape => false',
'    --        )',
'    --    );',
'    apex_json.open_object();',
'    apex_json.open_array(''dateData'');',
'    for l_row_num in 1 .. l_column_value_list(1).value_list.count loop',
'        begin',
'            apex_json.open_object();',
'            -- Set the column values of our current row so that apex_plugin_util.replace_substitutions',
'            -- can do substitutions for columns contained in the region source query.',
'            apex_plugin_util.set_component_values (',
'                p_column_value_list => l_column_value_list,',
'                p_row_num           => l_row_num );',
'',
'            -- get the day',
'            l_value := apex_plugin_util.get_value_as_varchar2 (',
'                               p_data_type   => l_column_value_list(l_day_column_no).data_type,',
'                               p_value       => l_column_value_list(l_day_column_no).value_list(l_row_num),',
'                               p_format_mask => ''YYYYMMDD'');',
'',
'            apex_json.write(''date'', l_value);',
'',
'            -- get the value',
'            l_value := apex_plugin_util.get_value_as_varchar2 (',
'                               p_data_type => l_column_value_list(l_value_column_no).data_type,',
'                               p_value     => l_column_value_list(l_value_column_no).value_list(l_row_num) );',
'',
'            apex_json.write(',
'                p_name       => ''value'',',
'                p_value      => to_number(l_value),',
'                p_write_null => false);',
'',
'',
'            -- get the label',
'            if p_region.attribute_13 is not null then',
'                l_value := apex_plugin_util.get_value_as_varchar2 (',
'                                   p_data_type   => l_column_value_list(l_label_column_no).data_type,',
'                                   p_value       => l_column_value_list(l_label_column_no).value_list(l_row_num) );',
'',
'                apex_json.write(''label'', l_value);',
'            end if;',
'',
'            apex_json.close_object();',
'',
'            apex_plugin_util.clear_component_values;',
'        exception when others then',
'            apex_plugin_util.clear_component_values;',
'            raise;',
'        end;',
'    end loop;',
'    apex_json.close_all();',
'',
'    return null;',
'exception when others then',
'    htp.p(''error: ''||apex_escape.html(sqlerrm));',
'    return null;',
'end ajax;',
'',
''))
,p_api_version=>1
,p_render_function=>'render'
,p_ajax_function=>'ajax'
,p_standard_attributes=>'SOURCE_SQL:INIT_JAVASCRIPT_CODE'
,p_substitute_attributes=>true
,p_version_scn=>1
,p_subscribe_plugin_settings=>true
,p_help_text=>'Heatmap calendar is a region type plugin that shows year calendar where days are arranged into columns by week, then grouped by month and years. The values are visualised as colored cells per day.'
,p_version_identifier=>'1.1'
,p_about_url=>'https://github.com/nikitsky/heatmap_calendar_apex_plugin'
,p_files_version=>62
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(354598643900238182806)
,p_plugin_id=>wwv_flow_imp.id(354598643583106077354)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>30
,p_static_id=>'attribute_01'
